test_setup_files.behavior_test.js:
const assert = require('assert');
const { Trie } = require('./build/trie.js');

const t = new Trie();
for (const w of ['cat', 'car', 'care', 'dog', 'do']) {
  t.insert(w);
}

assert.deepStrictEqual(t.wordsWithPrefix('ca'), ['car', 'care', 'cat']);
assert.deepStrictEqual(t.wordsWithPrefix('do'), ['do', 'dog']);
assert.deepStrictEqual(t.wordsWithPrefix('xyz'), []);
assert.deepStrictEqual(t.wordsWithPrefix(''), ['car', 'care', 'cat', 'do', 'dog']);
assert.deepStrictEqual(t.wordsWithPrefix('c'), ['car', 'care', 'cat']);

// duplicate insert must not duplicate the result
t.insert('cat');
assert.deepStrictEqual(t.wordsWithPrefix('cat'), ['cat']);

console.log('ok');

