export class Trie {
  private children: Map<string, Trie> = new Map();
  private isEnd: boolean = false;

  insert(word: string): void {
    let node: Trie = this;
    for (const ch of word) {
      let next = node.children.get(ch);
      if (!next) {
        next = new Trie();
        node.children.set(ch, next);
      }
      node = next;
    }
    node.isEnd = true;
  }

  wordsWithPrefix(prefix: string): string[] {
    let node: Trie = this;
    for (const ch of prefix) {
      const next: Trie | undefined = node.children.get(ch);
      if (!next) return [];
      node = next;
    }
    const results: string[] = [];
    node.collect(prefix, results);
    return results.sort();
  }

  private collect(prefix: string, results: string[]): void {
    if (this.isEnd) results.push(prefix);
    for (const [ch, child] of this.children) {
      child.collect(prefix + ch, results);
    }
  }
}

